/**
 * MECHPLANT — Offline Lightweight 3D Engine Shim (Compatible con API Three.js r128)
 * Reemplázalo cuando desees por el bundle oficial three.min.js (r128) de 600 KB.
 */
(function (global) {
  "use strict";

  class Vector2 {
    constructor(x = 0, y = 0) { this.x = x; this.y = y; }
    set(x, y) { this.x = x; this.y = y; return this; }
  }

  class Vector3 {
    constructor(x = 0, y = 0, z = 0) { this.x = x; this.y = y; this.z = z; }
    set(x, y, z) { this.x = x; this.y = y; this.z = z; return this; }
    copy(v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; }
    add(v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; }
    sub(v) { this.x -= v.x; this.y -= v.y; this.z -= v.z; return this; }
    multiplyScalar(s) { this.x *= s; this.y *= s; this.z *= s; return this; }
    length() { return Math.hypot(this.x, this.y, this.z); }
    normalize() { const l = this.length() || 1; return this.multiplyScalar(1 / l); }
    clone() { return new Vector3(this.x, this.y, this.z); }
  }

  class Color {
    constructor(hex = 0xffffff) { this.set(hex); }
    set(hex) {
      this.hex = typeof hex === "number" ? hex : parseInt(String(hex).replace("#", ""), 16) || 0x0095d9;
      return this;
    }
    toCSS(alpha = 1) {
      const r = (this.hex >> 16) & 255;
      const g = (this.hex >> 8) & 255;
      const b = this.hex & 255;
      return `rgba(${r},${g},${b},${alpha})`;
    }
  }

  class Box3 {
    constructor() { this.min = new Vector3(-1, -1, -1); this.max = new Vector3(1, 1, 1); }
    setFromObject() { return this; }
    getCenter(target = new Vector3()) { return target.set(0, 0, 0); }
    getSize(target = new Vector3()) { return target.set(3, 2, 3); }
  }

  class Object3D {
    constructor() {
      this.name = "";
      this.children = [];
      this.parent = null;
      this.position = new Vector3();
      this.rotation = new Vector3();
      this.scale = new Vector3(1, 1, 1);
      this.userData = {};
      this.visible = true;
    }
    add(obj) {
      if (!obj) return this;
      obj.parent = this;
      this.children.push(obj);
      return this;
    }
    remove(obj) {
      this.children = this.children.filter(c => c !== obj);
      return this;
    }
    traverse(cb) {
      cb(this);
      this.children.forEach(c => c.traverse(cb));
    }
    clone() {
      const copy = new this.constructor();
      copy.name = this.name;
      copy.position.copy(this.position);
      copy.rotation.copy(this.rotation);
      copy.scale.copy(this.scale);
      copy.geometry = this.geometry;
      copy.material = this.material;
      return copy;
    }
  }

  class Group extends Object3D {}
  class Scene extends Object3D {
    constructor() { super(); this.background = new Color(0x081220); }
  }

  class PerspectiveCamera extends Object3D {
    constructor(fov = 45, aspect = 1.6, near = 0.1, far = 1000) {
      super();
      this.fov = fov; this.aspect = aspect; this.near = near; this.far = far;
      this.position.set(4, 2.5, 5);
      this.target = new Vector3(0, 0, 0);
    }
    lookAt(x, y, z) {
      if (typeof x === "object") this.target.copy(x);
      else this.target.set(x, y, z);
    }
    updateProjectionMatrix() {}
  }

  class MeshStandardMaterial {
    constructor(opts = {}) {
      this.color = new Color(opts.color !== undefined ? opts.color : 0x0095d9);
      this.opacity = opts.opacity !== undefined ? opts.opacity : 1;
      this.transparent = Boolean(opts.transparent);
      this.wireframe = Boolean(opts.wireframe);
    }
    clone() {
      return new MeshStandardMaterial({
        color: this.color.hex,
        opacity: this.opacity,
        transparent: this.transparent,
        wireframe: this.wireframe
      });
    }
  }

  class BoxGeometry { constructor(w = 1, h = 1, d = 1) { this.type = "box"; this.w = w; this.h = h; this.d = d; } }
  class CylinderGeometry { constructor(rt = 1, rb = 1, h = 1) { this.type = "cyl"; this.w = Math.max(rt, rb) * 2; this.h = h; this.d = this.w; } }
  class ConeGeometry extends CylinderGeometry { constructor(r = 1, h = 1) { super(0.05, r, h); } }
  class SphereGeometry { constructor(r = 1) { this.type = "sph"; this.w = r * 2; this.h = r * 2; this.d = r * 2; } }
  class TorusGeometry { constructor(r = 1, t = 0.2) { this.type = "tor"; this.w = (r + t) * 2; this.h = t * 2; this.d = this.w; } }

  class Mesh extends Object3D {
    constructor(geometry = new BoxGeometry(), material = new MeshStandardMaterial()) {
      super();
      this.geometry = geometry;
      this.material = material;
      this.isMesh = true;
    }
  }

  class AmbientLight extends Object3D { constructor(c, i) { super(); this.color = new Color(c); this.intensity = i; } }
  class DirectionalLight extends Object3D { constructor(c, i) { super(); this.color = new Color(c); this.intensity = i; } }
  class GridHelper extends Object3D { constructor(size = 10, div = 10) { super(); this.size = size; this.div = div; } }

  class Raycaster {
    setFromCamera() {}
    intersectObjects(objs) { return []; }
  }

  class OrbitControls {
    constructor(camera, domElement) {
      this.camera = camera;
      this.domElement = domElement;
      this.target = new Vector3(0, 0, 0);
      this.yaw = 0.65;
      this.pitch = 0.35;
      this.distance = 6.2;
      this.enableDamping = true;

      let dragging = false, lx = 0, ly = 0;
      domElement.addEventListener("pointerdown", e => { dragging = true; lx = e.clientX; ly = e.clientY; });
      window.addEventListener("pointerup", () => { dragging = false; });
      window.addEventListener("pointermove", e => {
        if (!dragging) return;
        this.yaw -= (e.clientX - lx) * 0.008;
        this.pitch = Math.max(-1.2, Math.min(1.2, this.pitch + (e.clientY - ly) * 0.008));
        lx = e.clientX; ly = e.clientY;
        this.update();
      });
      domElement.addEventListener("wheel", e => {
        e.preventDefault();
        this.distance = Math.max(2.2, Math.min(16, this.distance + e.deltaY * 0.004));
        this.update();
      }, { passive: false });
      this.update();
    }
    update() {
      this.camera.position.x = this.target.x + this.distance * Math.cos(this.pitch) * Math.sin(this.yaw);
      this.camera.position.y = this.target.y + this.distance * Math.sin(this.pitch);
      this.camera.position.z = this.target.z + this.distance * Math.cos(this.pitch) * Math.cos(this.yaw);
      this.camera.lookAt(this.target);
    }
  }

  class GLTFLoader {
    load(_url, _onLoad, _onProgress, onError) {
      if (typeof onError === "function") onError(new Error("Usando generador paramétrico CAD local"));
    }
  }

  class WebGLRenderer {
    constructor(opts = {}) {
      this.domElement = opts.canvas || document.createElement("canvas");
      this.ctx = this.domElement.getContext("2d");
      this.width = 800;
      this.height = 500;
    }
    setSize(w, h) {
      this.width = w; this.height = h;
      this.domElement.width = w; this.domElement.height = h;
    }
    setPixelRatio() {}
    render(scene, camera) {
      const ctx = this.ctx;
      if (!ctx) return;
      const w = this.width, h = this.height;
      ctx.fillStyle = "#081220";
      ctx.fillRect(0, 0, w, h);

      // Grilla Blueprint de fondo
      ctx.strokeStyle = "#163254";
      ctx.lineWidth = 1;
      for (let gx = 0; gx < w; gx += 32) { ctx.beginPath(); ctx.moveTo(gx, 0); ctx.lineTo(gx, h); ctx.stroke(); }
      for (let gy = 0; gy < h; gy += 32) { ctx.beginPath(); ctx.moveTo(0, gy); ctx.lineTo(w, gy); ctx.stroke(); }

      const yaw = Math.atan2(camera.position.x, camera.position.z);
      const pitch = Math.atan2(camera.position.y, Math.hypot(camera.position.x, camera.position.z));
      const zoom = (Math.min(w, h) * 0.9) / Math.max(camera.position.length(), 2.2);

      const project = (x, y, z) => {
        const x1 = x * Math.cos(yaw) - z * Math.sin(yaw);
        const z1 = x * Math.sin(yaw) + z * Math.cos(yaw);
        const y2 = y * Math.cos(pitch) - z1 * Math.sin(pitch);
        const z2 = y * Math.sin(pitch) + z1 * Math.cos(pitch);
        return { sx: w / 2 + x1 * zoom, sy: h / 2 - y2 * zoom, depth: z2 };
      };

      const meshes = [];
      scene.traverse(obj => {
        if (obj.isMesh && obj.visible) {
          let wx = 0, wy = 0, wz = 0, cur = obj;
          while (cur) { wx += cur.position.x; wy += cur.position.y; wz += cur.position.z; cur = cur.parent; }
          const p = project(wx, wy, wz);
          meshes.push({ obj, p, zoom });
        }
      });

      meshes.sort((a, b) => a.p.depth - b.p.depth);

      meshes.forEach(({ obj, p }) => {
        const g = obj.geometry || { w: 1, h: 1, d: 1 };
        const rw = Math.max((g.w || 1) * zoom * 0.45, 10);
        const rh = Math.max((g.h || 1) * zoom * 0.45, 10);
        const alpha = obj.material ? obj.material.opacity : 0.9;
        ctx.fillStyle = obj.material ? obj.material.color.toCSS(alpha * 0.72) : "rgba(0,149,217,0.72)";
        ctx.strokeStyle = "#38BDF8";
        ctx.lineWidth = 1.4;
        ctx.beginPath();
        ctx.roundRect(p.sx - rw / 2, p.sy - rh / 2, rw, rh, 4);
        ctx.fill();
        ctx.stroke();
      });
    }
  }

  global.THREE = {
    Vector2, Vector3, Color, Box3, Object3D, Group, Scene,
    PerspectiveCamera, MeshStandardMaterial,
    BoxGeometry, CylinderGeometry, ConeGeometry, SphereGeometry, TorusGeometry,
    Mesh, AmbientLight, DirectionalLight, GridHelper,
    Raycaster, OrbitControls, GLTFLoader, WebGLRenderer
  };
})(typeof window !== "undefined" ? window : this);
